module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);
    reg [1:0] a_reg;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            a_reg <= 2'b00;
        end else begin
            a_reg <= {a_reg[0], a};
        end
    end

    assign rise = (a_reg == 2'b01);
    assign down = (a_reg == 2'b10);
endmodule
